// Coefficients of the closed-form strapdown INS propagation of
// Goppert, James, et al. "A Closed-form Solution for the Strapdown Inertial Navigation Initial Value Problem."
// arXiv preprint arXiv:2310.04886 (2023), where theta is the rotation angle over the integration interval [rad].
//
// Each is the sum (-1)^n theta^2n / (2n+k)! derived in the proof of Theorem 1, with k = 2, 3 and 4
// respectively. The numerator of every closed form is a difference of nearly equal terms, so below
// the switch thresholds the series is used instead; the thresholds and series lengths are chosen by
// trig_series_derivation.py to bound the relative error over all theta.

// (1 - cos(theta)) / theta^2
// Series below theta = 0.38, worst-case relative error 3.19e-07 at theta = 0.442
template <typename T>
T c1(const T theta_sq)
{
	if (theta_sq < T(0.1444)) {
		return T(1.0/2.0) + theta_sq * (T(-1.0/24.0) + theta_sq * (T(1.0/720.0)));
	}

	const T theta = std::sqrt(theta_sq);
	return (T(1) - std::cos(theta)) / theta_sq;
}

// (theta - sin(theta)) / theta^3
// Series below theta = 0.54, worst-case relative error 6.91e-07 at theta = 0.643
template <typename T>
T c2(const T theta_sq)
{
	if (theta_sq < T(0.2916)) {
		return T(1.0/6.0) + theta_sq * (T(-1.0/120.0) + theta_sq * (T(1.0/5040.0)));
	}

	const T theta = std::sqrt(theta_sq);
	return (theta - std::sin(theta)) / (theta_sq * theta);
}

// (theta^2 / 2 + cos(theta) - 1) / theta^4
// Series below theta = 1.28, worst-case relative error 6.18e-07 at theta = 1.428
template <typename T>
T c3(const T theta_sq)
{
	if (theta_sq < T(1.6384)) {
		return T(1.0/24.0) + theta_sq * (T(-1.0/720.0) + theta_sq * (T(1.0/40320.0) + theta_sq * (T(-1.0/3628800.0))));
	}

	const T theta = std::sqrt(theta_sq);
	return (T(0.5) * theta_sq + std::cos(theta) - T(1)) / (theta_sq * theta_sq);
}

